{
  "passages": [
    {
      "id": "m51",
      "about_topic": true,
      "says": "fact: motorcycles, bicycles, limited-speed motorcycles and mopeds often pull to the side; rule: do not take that as an invitation to pass in the same lane; rule: if passing these vehicles, do it by changing lanes"
    },
    {
      "id": "m1",
      "about_topic": true,
      "says": "fact: changing position on the road involves changing lanes or overtaking and passing another vehicle"
    },
    {
      "id": "m4",
      "about_topic": true,
      "says": "rule: be sure there is enough space and time before beginning the move safely"
    },
    {
      "id": "m2",
      "about_topic": true,
      "says": "definition: passing is changing lanes to move past a slower vehicle"
    },
    {
      "id": "m3",
      "about_topic": true,
      "says": "facts: speed limits exist but speeds differ; some road users are usually slower; a driver may want to pass some slow-moving vehicles while following them"
    },
    {
      "id": "m5",
      "about_topic": true,
      "says": "rule: never overtake and pass unless sure it can be done without danger"
    },
    {
      "id": "m72",
      "about_topic": true,
      "says": "rule: do not pass moving snow plows under any conditions"
    },
    {
      "id": "m6",
      "about_topic": true,
      "says": "rule: if in doubt, do not pass"
    },
    {
      "id": "m8",
      "about_topic": true,
      "says": "lead: the following steps are for passing a vehicle"
    },
    {
      "id": "m9",
      "about_topic": true,
      "says": "procedure step: signal and check before moving into the passing lane"
    },
    {
      "id": "m10",
      "about_topic": true,
      "says": "procedure step: watch for hidden bicycles/small vehicles, left-turning vehicles, and vehicles or pedestrians entering the road"
    },
    {
      "id": "m11",
      "about_topic": true,
      "says": "procedure steps: change lanes only after signalling; after overtaking signal to move back and make the lane change when the front is visible in the inside mirror"
    },
    {
      "id": "m12",
      "about_topic": true,
      "says": "procedure step: be careful not to cut off a vehicle"
    },
    {
      "id": "m13",
      "about_topic": true,
      "says": "procedure step: if the vehicle being passed speeds up, do not race and go back to the original lane"
    },
    {
      "id": "m85",
      "about_topic": true,
      "says": "rule: do not speed up when another driver is trying to pass; it is unlawful and dangerous"
    },
    {
      "id": "m14",
      "about_topic": true,
      "says": "figure: diagram showing how to pass another vehicle"
    },
    {
      "id": "m15",
      "about_topic": true,
      "says": "rule: passing within 30 m of a pedestrian crossover is not permitted"
    },
    {
      "id": "m17",
      "about_topic": true,
      "says": "rule: passing left of a centreline is not permitted 30 m from a bridge, viaduct or tunnel"
    },
    {
      "id": "m18",
      "about_topic": true,
      "says": "rule: do not attempt to pass at a hill crest or curve when vision is obstructed and clear distance is insufficient"
    },
    {
      "id": "m50",
      "about_topic": true,
      "says": "rule: when passing parked vehicles, watch for people opening doors or doors opened for loading/unloading"
    },
    {
      "id": "m84",
      "about_topic": true,
      "says": "rule: when faster traffic wants to pass, move right and let it pass in safety"
    },
    {
      "id": "m89",
      "about_topic": true,
      "says": "rule: when being passed on an undivided road with the passing driver in the opposite lane, watch oncoming traffic, move right, and be prepared to slow"
    },
    {
      "id": "m90",
      "about_topic": true,
      "says": "rule: trucks are not allowed in the far left-hand lane on many high-speed roads with 3+ lanes; fact: the next lane is the truck passing lane; rule: move right when a truck wants to pass"
    },
    {
      "id": "m52",
      "about_topic": true,
      "says": "figure: diagram showing how to pass another vehicle"
    },
    {
      "id": "m39",
      "about_topic": true,
      "says": "rule: be very careful when passing other vehicles at night"
    },
    {
      "id": "m40",
      "about_topic": true,
      "says": "lead: night-passing steps when the driver has to pass and the way is clear"
    },
    {
      "id": "m41",
      "about_topic": true,
      "says": "procedure step: switch to low beams when approaching a vehicle from behind"
    },
    {
      "id": "m42",
      "about_topic": true,
      "says": "procedure steps: signal, check, and pull out to pass; switch to high beams while alongside to see ahead"
    },
    {
      "id": "m43",
      "about_topic": true,
      "says": "procedure step: pull back into the right lane and signal when the front is visible in the rear view mirror because the driver is far enough ahead"
    },
    {
      "id": "m27",
      "about_topic": true,
      "says": "figure: a passing or climbing lane"
    },
    {
      "id": "m28",
      "about_topic": true,
      "says": "facts: some roads have passing or climbing lanes; their purpose is to let slower vehicles move right so faster vehicles pass left"
    },
    {
      "id": "m29",
      "about_topic": true,
      "says": "facts: an advance sign tells drivers they will soon have a chance to pass; another sign warns the lane is ending so drivers can merge safely"
    },
    {
      "id": "m38",
      "about_topic": true,
      "says": "rules: may drive on the right shoulder only to pass a left-turning vehicle and only if paved; may not pass on the left shoulder"
    },
    {
      "id": "m35",
      "about_topic": true,
      "says": "fact: most passing is done on the left; rule: may pass on the right on multi-lane or one-way roads and when overtaking a streetcar or left-turning vehicle"
    },
    {
      "id": "m36",
      "about_topic": true,
      "says": "fact: passing on the right can be more dangerous than passing on the left"
    },
    {
      "id": "m37",
      "about_topic": true,
      "says": "rules: wait for a slower vehicle in front to move right; do not suddenly change lanes and pass on the right"
    },
    {
      "id": "m61",
      "about_topic": true,
      "says": "figure: a vehicle stopped the required 2 m behind the rear doors of a stopped streetcar"
    },
    {
      "id": "m62",
      "about_topic": true,
      "says": "rule: must pass streetcars on the right unless on a one-way road"
    },
    {
      "id": "m63",
      "about_topic": true,
      "says": "rule: at streetcar stops stay at least 2 m behind the rear doors where passengers are getting off or on; exception for stops with a set-aside passenger area"
    },
    {
      "id": "m64",
      "about_topic": true,
      "says": "rule: pass set-aside streetcar passenger areas at a reasonable speed and be prepared for pedestrians' sudden or unexpected moves"
    }
  ],
